insert into public.exercise_copy (
  exercise_id, setup_steps, should_feel, stop_if, find_it, dos, donts, updated_at
) values
  ('dumbbell-goblet-squat', '["Pick one dumbbell and hold it upright against your chest, both hands cupping the top end.","Stand with feet a little wider than your hips and turn your toes out slightly.","Sit down between your knees, keeping your chest tall and elbows inside your thighs.","Go as deep as feels smooth, then push the floor away to stand."]'::jsonb, 'Your thighs and glutes working, with your weight balanced over your whole foot.', 'If your lower back rounds or a knee pinches, stop and tap Swaps for a kinder version.', 'Find the dumbbell rack by the mirrors, start around 10-14 kg, and use any open floor space.', '["Keep the dumbbell touching your chest so it cannot pull you forward.","Share your weight across your heel, big toe, and little toe.","Push the floor away to stand tall."]'::jsonb, '["Do not let your knees cave inward; aim them toward your toes.","Do not lift your heels to get lower; stop where your whole foot stays down.","Do not drop into the bottom; keep your legs working on the way down."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('barbell-squat', '["Set the rack hooks just below shoulder height and the safety arms just below your lowest squat.","Step under the bar, rest it across your upper back, and place both hands evenly.","Stand up with the bar, take two short steps back, and set your feet about shoulder-width apart.","Sit down between your knees, then press through both feet to stand."]'::jsonb, 'Your thighs and glutes working while your middle stays firm and your whole foot stays grounded.', 'If the bar presses your neck, your wrists ache, or your back folds, re-rack it and tap Swaps.', 'Head to the squat racks in the weights area; an empty 15-20 kg bar is plenty for a first try.', '["Tighten your middle as if you expect a cough so your torso stays steady.","Point your knees the same way as your toes to give your hips room.","Stand by driving both feet into the floor."]'::jsonb, '["Do not rest the bar on your neck; keep it on the muscle below it.","Do not walk far from the rack; two short steps make re-racking easier.","Do not let your knees cave as you stand; that shifts pressure into them."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-leg-press', '["Adjust the seat so your knees start near a right angle and your lower back stays on the pad.","Place both feet shoulder-width apart in the middle of the large footplate.","Choose a light pin setting, around 20-40 kg, then release the safety handles.","Lower the plate until your knees feel comfortably bent, then press it away without locking them."]'::jsonb, 'Your thighs and glutes working, with your hips and lower back heavy against the seat.', 'If your hips curl off the pad or a knee pinches, stop, shorten the depth, and tap Swaps.', 'Look in the leg-machine row for a reclined seat facing a broad footplate; start with 20-40 kg on the pin.', '["Press through your whole foot so your heels stay planted.","Let your knees travel in line with your middle toes.","Lower only as far as your back can stay against the pad."]'::jsonb, '["Do not place your feet so low that your heels peel off the plate.","Do not press your knees together; that makes them carry the wrong angle.","Do not snap your knees straight or lift your hips at the top."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-bulgarian-split-squat', '["Stand about two foot-lengths in front of a flat bench, with your feet still hip-width apart.","Rest the top of one foot on the bench and keep most of your weight on the front leg.","Hold a dumbbell in each hand, or start without them while you learn the balance.","Lower your back knee toward the floor, then drive through the front foot to rise."]'::jsonb, 'Your front thigh and glute working, with your whole front foot grounded and your torso steady.', 'If the front knee pinches, the back hip pulls sharply, or balance feels unsafe, tap Swaps.', 'Take a flat bench near the dumbbell rack; begin bodyweight or with 4-8 kg in each hand.', '["Keep your feet hip-width apart so you have a stable base.","Lean your chest forward a little to load the front glute.","Push the front foot down instead of springing off the back toes."]'::jsonb, '["Do not stand too close to the bench; a rising front heel means you need more space.","Do not put most of your weight on the bench leg; it is there for balance.","Do not place both feet on one narrow line; that makes every rep wobble."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('bodyweight-squat', '["Stand in open floor space with your feet just wider than hip-width.","Turn your toes out a little and reach both arms forward for balance.","Send your hips down between your knees while keeping your full foot on the floor.","Pause at a comfortable depth, then press the floor away to stand."]'::jsonb, 'Your thighs and glutes working evenly, with steady pressure under both feet.', 'If a knee pinches or your back rounds before a comfortable depth, use a bench target or tap Swaps.', 'Use the stretching area, a quiet patch by the mirrors, or any clear floor space; no gear is needed.', '["Reach your hands forward to help your chest stay tall.","Track your knees over the middle of your feet.","Choose a depth where your heels stay heavy."]'::jsonb, '["Do not force your thighs below parallel if your back starts to curl.","Do not rise onto your toes; that sends you forward instead of up.","Do not let one knee fall inward while the other stays straight."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('bodyweight-reverse-lunge', '["Stand with feet hip-width apart and leave a clear step of space behind you.","Step one foot straight back and land softly on the ball of that foot.","Lower the back knee toward the floor while the front foot stays flat.","Press through the front foot to return, then finish the side before switching."]'::jsonb, 'Your front thigh and glute working, with the front foot grounded and your torso quiet.', 'If the front knee pinches or you cannot return without a hard wobble, shorten the step or tap Swaps.', 'Use the turf or stretching area near a rail or wall; this version needs no weights.', '["Step back far enough that your front heel stays down.","Aim the front knee toward the middle toes.","Drive the front foot into the floor to come home."]'::jsonb, '["Do not step directly behind your front foot; keep a hip-width base.","Do not bounce the back knee off the floor.","Do not shove off the back toes; the front leg should bring you up."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('barbell-romanian-deadlift', '["Set rack hooks just below hip height, grip the bar outside your legs, and stand with it against your thighs.","Soften your knees, tighten your middle, and keep the bar close to your body.","Push your hips back as the bar slides down your thighs toward your shins.","Stop at a strong back-of-thigh stretch, then push your hips forward to stand."]'::jsonb, 'Your hamstrings and glutes working, with the bar close and your weight centered over both feet.', 'If your lower back takes over or you feel a sharp pull behind a knee, rack the bar and tap Swaps.', 'Use a squat rack in the weights area; set the empty 15-20 kg bar on hooks just below hip height.', '["Keep the bar brushing your legs so it cannot pull your back forward.","Send your hips toward the wall behind you.","Stand tall by squeezing your glutes."]'::jsonb, '["Do not bend your knees into a squat; keep only a soft bend.","Do not reach the bar toward the floor after your back starts to round.","Do not lean backward at the top; finish stacked over your feet."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-romanian-deadlift', '["Choose two dumbbells and hold them in front of your thighs with palms facing you.","Set your feet hip-width apart, soften your knees, and make your torso firm.","Push your backside toward the wall as the dumbbells travel down beside your legs.","Stop around mid-shin or at a strong hamstring stretch, then stand tall."]'::jsonb, 'The backs of your thighs and your glutes working while your trunk moves as one piece.', 'If your lower back aches or the stretch turns sharp near your sitting bones, set the weights down and tap Swaps.', 'Pick a pair of 6-10 kg dumbbells from the rack and use a clear patch in front of it.', '["Keep the dumbbells directly below your shoulders.","Think of closing a car door with your hips.","End the descent when the hamstring stretch is strongest."]'::jsonb, '["Do not squat the dumbbells toward the floor.","Do not round your shoulders just to make the weights travel lower.","Do not let the dumbbells drift out in front of your toes."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('barbell-deadlift', '["Stand with the bar over the middle of your feet, about a thumb-width from your shins.","Push your hips back, bend your knees, and grip the bar just outside your legs.","Lift your chest enough to make your back firm, then push the floor away and stand.","Send your hips back, bend your knees after the bar passes them, and set it down."]'::jsonb, 'Your legs, glutes, and hamstrings working, with full-foot pressure and the bar close to you.', 'If your back rounds before the bar moves or you feel a sharp groin or back tug, lower it and tap Swaps.', 'Find the rubber lifting platforms by the racks; start around 20-30 kg with full-size light plates.', '["Pull gently on the bar before lifting to remove any loose clank.","Push the floor away instead of yanking with your arms.","Reset your feet and grip before each clean rep."]'::jsonb, '["Do not jerk the bar from the floor; it should leave smoothly.","Do not let your hips shoot up before your chest.","Do not swing the bar around your knees; keep it close to your legs."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('cable-pull-through', '["Clip a rope to the lowest cable setting and choose a light pin, around 10-20 kg.","Face away, straddle the rope, and hold one rope end in each hand.","Walk forward until the cable stays taut, then soften your knees and push your hips back.","Let the rope pass between your legs, then squeeze your glutes to stand tall."]'::jsonb, 'Your glutes and hamstrings working, with both feet planted and the cable pulling from behind.', 'If the rope rubs your groin or your lower back arches at the top, stop and tap Swaps.', 'Find a cable tower by the upper-body machines and a rope on its attachment rack; start around 10-20 kg.', '["Step far enough forward that the stack never goes slack.","Reach your hips back toward the machine.","Finish tall by squeezing your glutes, not by leaning back."]'::jsonb, '["Do not squat straight down; the movement comes from your hips.","Do not pull the rope forward with your arms.","Do not throw your shoulders behind your feet at the finish."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-back-extension', '["Adjust the foot brace so your knees stay softly bent and your hips sit firmly against the seat.","Set the rolling pad across your upper back, lower the lap pad snugly, and choose 10-20 kg.","Sit tall with your ribs down, then let your torso tip forward a small amount.","Press your upper back into the roller until you are upright, then return slowly."]'::jsonb, 'Your glutes and the muscles beside your lower back working while your hips stay fixed in the seat.', 'If your lower spine feels pinched or the roller presses your neck, stop, readjust, and tap Swaps.', 'Look for a chair with a curved back roller and foot brace in the core or leg area; start around 10-20 kg.', '["Keep the movement small enough that your hips stay planted.","Press both feet into the brace for a steady base.","Finish upright with your ribs over your hips."]'::jsonb, '["Do not throw your head back to move the roller.","Do not arch past upright; that squeezes the lower spine.","Do not let your hips slide forward under the lap pad."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('barbell-hip-thrust', '["Brace a flat bench against a rack or wall and sit with your shoulder blades at its long edge.","Roll a padded bar over your legs and settle it into the crease at the front of your hips.","Plant your feet hip-width apart, with heels close enough that your shins finish nearly upright.","Drive through both feet until hips reach knee height, pause, then lower under control."]'::jsonb, 'Your glutes working hard at the top, with your feet and upper back steady and no lower-back squeeze.', 'If the bar hurts your hip bones despite the pad or your lower back pinches, unload it and tap Swaps.', 'Use a rack or platform, a flat bench, and a thick bar pad; start around 20-30 kg total.', '["Anchor the bench so it cannot slide behind you.","Keep your shins close to upright at the top.","Pause and squeeze your glutes before lowering."]'::jsonb, '["Do not put the bar on your stomach; keep it in the hip crease.","Do not rest only your neck on the bench; use the bottom of your shoulder blades.","Do not fling your ribs upward to chase extra height."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-glute-bridge', '["Lie on a mat with knees bent, feet flat, and heels a comfortable distance from your hips.","Place one dumbbell across your hip creases and hold both ends so it stays centered.","Let your ribs settle down, then press through both feet to lift your hips.","Stop when knees, hips, and shoulders form a line, squeeze, then lower softly."]'::jsonb, 'Your glutes working with both heels grounded and your lower back staying comfortable.', 'If your hamstrings cramp or your lower back pinches, move your feet slightly and tap Swaps if it continues.', 'Take a mat and one 8-14 kg dumbbell to the stretching area, away from the busy rack.', '["Hold both ends of the dumbbell so it cannot roll.","Set your ribs before your hips leave the floor.","Pause when your glutes feel strongest."]'::jsonb, '["Do not push from your toes; keep your heels heavy.","Do not lift your ribs higher than your hips.","Do not bounce the dumbbell off your body between reps."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-hip-thrust', '["Set a flat bench against a wall and sit with the bottom of your shoulder blades on its edge.","Place one dumbbell lengthwise across your hip creases and hold it at both ends.","Plant your feet hip-width apart and tuck your chin so you look toward your knees.","Push the floor away, lift your hips to knee height, pause, then lower."]'::jsonb, 'Your glutes doing the lift, with your whole feet down and your shoulder blades anchored to the bench.', 'If the bench presses into your neck or your lower back pinches, reposition and tap Swaps.', 'Pair a flat bench with one 8-16 kg dumbbell near the rack, ideally where the bench can meet a wall.', '["Check that the bench cannot slide before you start.","Keep your gaze forward so your ribs stay down.","Finish with your shins close to upright."]'::jsonb, '["Do not balance on your neck; keep your shoulder blades on the edge.","Do not let the dumbbell roll up onto your stomach.","Do not arch beyond a level hip position."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-hip-abduction', '["Sit back in the seat and use the start lever to bring the leg pads to a comfortable narrow position.","Place the pads against the outside of your knees or lower thighs and set both feet on the rests.","Choose a light pin, around 15-30 kg, and hold the side handles.","Press your knees apart, pause before your hips shift, then return slowly."]'::jsonb, 'The outer sides of your glutes working, with your hips level and your back still against the seat.', 'If the front or inside of a hip pinches or a knee twists, narrow the start position and tap Swaps.', 'Look in the leg-machine row for a chair with two pads outside the knees; start around 15-30 kg.', '["Keep both sides of your hips heavy on the seat.","Lead the press with your knees.","Pause open before easing the pads inward."]'::jsonb, '["Do not bounce the stack to force the pads wider.","Do not swing your whole torso forward and back.","Do not let the plates fully rest between reps."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('cable-standing-glute-kickback', '["Clip an ankle strap to the lowest cable setting and choose 2.5-7.5 kg on the pin.","Face the tower, secure the strap around one ankle, and hold the frame with both hands.","Step back until the cable is taut, soften the standing knee, and lean forward slightly.","Sweep the strapped leg behind you without turning your hips, then return slowly."]'::jsonb, 'One glute working while your standing foot stays steady and your waist stays quiet.', 'If the strap pulls at your ankle or your lower back tightens, unclip it and tap Swaps.', 'Find a cable tower and the nearby basket of ankle straps; start with 2.5-7.5 kg on the lowest pulley.', '["Hold the frame so balance does not steal the rep.","Squeeze the working glute before the leg travels high.","Keep the return smooth and quiet."]'::jsonb, '["Do not kick so high that your lower back arches.","Do not turn your toes and hips open to gain distance.","Do not let the stack slam at the front."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-glute-kickback', '["Choose 10-20 kg on the pin and adjust the knee pad, if it moves, so your hips meet the machine pivot.","Set up on all fours on the machine: one knee on the pad, hands on the handles, and your working foot resting on the plate behind you.","Start with the working knee under your hip, then press the footplate back with your heel.","Stop before your back arches and return without resting the stack, then switch sides."]'::jsonb, 'The working-side glute pushing the plate while your supported knee and hips stay comfortable.', 'If the support pad hurts your knee or your lower back pinches, add padding, readjust, and tap Swaps.', 'Look by the leg machines for a kneeling pad and one moving footplate; start around 10-20 kg.', '["Drive the footplate back through your heel.","Keep both hip bones facing the floor.","Bring the knee forward slowly without resting the plates."]'::jsonb, '["Do not snap the working knee straight.","Do not turn your hips open as the plate moves.","Do not drop the stack at the end of the return."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-leg-extension', '["Adjust the backrest so your knees line up with the machine hinge beside them.","Move the shin roller to sit above your ankles, not on your feet.","Choose 10-20 kg on the pin, sit back, and hold the side handles.","Lift the roller until your legs are almost straight, then lower it without dropping the stack."]'::jsonb, 'The fronts of your thighs working while your hips and back stay planted in the seat.', 'If you feel pressure behind the kneecap or the roller digs into your ankles, stop, readjust, and tap Swaps.', 'Find the chair with a padded roller in front of the shins in the leg-machine row; start around 10-20 kg.', '["Match your knees to the machine hinge before moving the pin.","Lift smoothly so the thigh muscles do the work.","Lower until the stack nearly touches, then start the next rep."]'::jsonb, '["Do not place the roller across your feet; it should sit above the ankles.","Do not kick your hips off the seat to finish a rep.","Do not snap your knees into a hard lock at the top."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-seated-hamstring-curl', '["Slide the backrest until the machine hinge at the side sits level with your knees.","Set the lower roller just above your heels and lower the thigh pad snugly above your knees.","Choose 10-20 kg on the pin, sit fully back, and hold the handles.","Pull your heels under the seat, pause, then let the roller travel forward slowly."]'::jsonb, 'The backs of your thighs working, with your hips down and the thigh pad holding you steady.', 'If you cramp behind a knee or your calf does most of the work, stop, adjust the roller, and tap Swaps.', 'Look for a seated leg machine with a thigh clamp and roller behind the legs; start around 10-20 kg.', '["Pull the roller back with your heels.","Keep your hips heavy against the seat.","Control the forward return until your legs are long."]'::jsonb, '["Do not leave the thigh pad loose enough for your legs to lift.","Do not raise your hips as your heels pull back.","Do not let the stack yank your legs straight."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-standing-calf-raises', '["Set the shoulder pads so you need only a tiny squat to get underneath them.","Choose 10-20 kg on the pin and place the balls of both feet on the edge of the step.","Stand tall into the pads with knees softly straight and heels hanging free.","Rise onto your toes, pause, then lower your heels below the step under control."]'::jsonb, 'Both calves working, with even pressure through the balls of your feet and the pads steady overhead.', 'If the back of your ankle pulls sharply or a foot slips on the edge, re-rack the weight and tap Swaps.', 'Look in the leg area for a tall machine with shoulder pads and a raised foot step; start around 10-20 kg.', '["Hold the handles before lifting the shoulder pads.","Travel all the way up and down through a smooth ankle range.","Keep both big toes pressing into the step."]'::jsonb, '["Do not bounce out of the bottom stretch.","Do not roll your ankles toward the outer edges of your feet.","Do not bend and straighten your knees to move the weight."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-bench-press', '["Sit on a flat bench with one dumbbell on each thigh and both feet planted.","Lie back while guiding the dumbbells to the sides of your chest.","Turn your palms forward and stack each wrist above its elbow.","Press the weights over your chest, then lower until your elbows are just below the bench top."]'::jsonb, 'Your chest and triceps working, with your upper back, feet, and wrists staying steady.', 'If the front of a shoulder pinches or a wrist buckles, bring the weights to your thighs and tap Swaps.', 'Take a flat bench beside the dumbbell rack and start with 4-8 kg in each hand.', '["Plant your feet before the first press.","Keep each wrist directly above its elbow.","Lower both dumbbells at the same speed."]'::jsonb, '["Do not point your elbows straight sideways; use a gentle diagonal.","Do not lower farther once the front of your shoulders rolls forward.","Do not bang the dumbbells together over your face."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('barbell-bench-press', '["Set the bench so your eyes sit just behind the bar and place the safety arms just below chest height.","Lie down with feet flat and grip the bar evenly, a little wider than your shoulders.","Lift the bar clear of the hooks and hold it over the middle of your chest.","Lower it to mid-chest with elbows on a diagonal, then press it back above you."]'::jsonb, 'Your chest and triceps working while your upper back and both feet stay firmly planted.', 'If a shoulder pinches or the bar drifts toward your neck, set it on the safeties and tap Swaps.', 'Find a bench station inside a rack; use the empty 15-20 kg bar first and ask for a spotter before plates.', '["Set the safety arms before you lie down.","Wrap your thumbs around the bar for a secure grip.","Touch the same mid-chest spot each rep."]'::jsonb, '["Do not set the hooks so high that you must reach your shoulders off the bench.","Do not bounce the bar off your chest.","Do not press with open thumbs; the bar can roll out of your hands."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-chest-press', '["Adjust the seat so the handles line up with the middle of your chest.","Choose 5-15 kg on the pin and set the start position so elbows sit a little behind your hands.","Sit with your back on the pad, feet flat, and wrists straight on the handles.","Press forward until your arms are long, then return before your shoulders roll forward."]'::jsonb, 'Your chest and triceps working, with your back supported and both hands pressing evenly.', 'If the handles pull your elbows far behind you or a shoulder pinches, adjust the seat or tap Swaps.', 'Look for a padded chair with two handles that press forward in the upper-body row; start around 5-15 kg.', '["Center your palms on the handles so your wrists stay straight.","Press both sides at the same pace.","End the return while your chest still feels open."]'::jsonb, '["Do not sit so low that the handles start near your face.","Do not shrug your shoulders toward your ears as you press.","Do not let the stack crash at the back of the rep."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-incline-bench-press', '["Raise an adjustable bench one or two notches above flat, about a 30-degree angle.","Sit with one dumbbell on each thigh, then lie back and guide them beside your upper chest.","Plant your feet and turn your palms forward with wrists above elbows.","Press up and slightly inward, then lower until your elbows reach just below your body."]'::jsonb, 'Your upper chest, shoulders, and triceps working while your feet and back stay settled.', 'If a shoulder catches at the bottom or your neck strains, bring the weights down and tap Swaps.', 'Use an adjustable bench by the dumbbells, set low, and start with 4-8 kg in each hand.', '["Use a low incline so your upper chest stays involved.","Keep your wrists stacked over your elbows.","Lower the dumbbells toward the top of your chest."]'::jsonb, '["Do not set the bench almost upright; that turns this into a shoulder press.","Do not flare your elbows straight out from your body.","Do not drop the weights faster than you can guide them."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-seated-overhead-press', '["Set the bench back almost upright, then sit with feet flat and dumbbells on your thighs.","Bring the dumbbells up beside your shoulders, palms turned forward or a little toward each other.","Keep your back on the pad and press both weights overhead without knocking them together.","Lower until the dumbbells return beside your shoulders, then repeat."]'::jsonb, 'Your shoulders and triceps working, with your back supported and your feet steady.', 'If the top or front of a shoulder pinches or your back lifts from the pad, set the weights down and tap Swaps.', 'Take an adjustable bench near the dumbbell rack, set it near upright, and start with 3-6 kg each.', '["Keep your ribs over your hips so the bench supports you.","Press the dumbbells slightly toward each other.","Guide the weights down to a comfortable shoulder height."]'::jsonb, '["Do not bounce the weights up with your legs.","Do not arch your lower back away from the pad.","Do not lower the dumbbells behind your shoulders."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('bodyweight-push-up', '["Choose a firm bench, rail, or wall height that lets you hold a straight body line.","Place your hands a little wider than your shoulders and step your feet back.","Tighten your glutes and middle, then lower your chest between your hands.","Keep elbows on a gentle diagonal and push the surface away to return."]'::jsonb, 'Your chest, triceps, and middle working while your body moves as one straight piece.', 'If a wrist or shoulder pinches or your hips keep sagging, raise your hands to a higher surface or tap Swaps.', 'Use a wall, sturdy rail, or flat bench in the stretching area; no weight is needed.', '["Choose a higher surface until every rep stays tidy.","Grip the edge or spread your fingers for stable hands.","Push the surface away at the bottom."]'::jsonb, '["Do not lead with your chin; bring your chest toward the surface.","Do not point your elbows straight out to the sides.","Do not let your hips sag or arrive after your chest."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('assisted-dip', '["Set the assistance pin around 30-45 kg; more stack weight means more help and an easier rep.","Climb the steps, grip the parallel handles, and place one knee at a time on the moving pad.","Let your shoulders stay down and lean your chest forward a little.","Bend your elbows to lower comfortably, then press the handles down until your arms are long."]'::jsonb, 'Your triceps and lower chest working, with your shoulders away from your ears and the pad steady.', 'If the front of a shoulder pinches or your hands go numb, let the pad rise, step off, and tap Swaps.', 'Find the tall assisted machine by the cable towers, with steps and a knee pad; start with 30-45 kg of help.', '["Choose more assistance when you need an easier starting point.","Keep your forearms close to upright as you lower.","Let the moving pad settle before stepping off."]'::jsonb, '["Do not jump off the knee pad while it is still low.","Do not let your shoulders creep toward your ears.","Do not lower past the point where your shoulders stay comfortable."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-pulldown', '["Choose 10-20 kg on the pin and adjust the thigh pad so it holds you down with feet flat.","Grip the wide bar a little beyond shoulder-width and sit with your chest gently lifted.","Pull the bar toward your collarbone by bringing your elbows down beside your ribs.","Pause near your upper chest, then let your arms reach long overhead without losing the seat."]'::jsonb, 'The sides of your back and your biceps working, with your thighs held down and your torso tall.', 'If a shoulder pinches overhead or your neck works harder than your back, reduce the weight or tap Swaps.', 'Look for a tall cable machine with a wide bar and thigh pad in the upper-body row; start around 10-20 kg.', '["Bring the bar toward your collarbone.","Lead the pull by driving your elbows down.","Let your arms reach long before the next rep."]'::jsonb, '["Do not pull toward your stomach; that turns it into a row and takes work away from your back.","Do not swing your torso backward to start the bar.","Do not pull the bar behind your neck; your shoulders lose their comfortable path."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-seated-cable-row', '["Clip on the close-grip handle and choose 10-20 kg on the pin.","Sit on the bench, place both feet on the plates, and keep your knees softly bent.","Hold the handle with long arms and sit tall before the stack leaves its rest.","Pull toward your lower ribs, keeping elbows close, then reach forward without rocking your torso."]'::jsonb, 'Your middle and upper back working with your biceps, while your feet stay braced and chest stays quiet.', 'If your lower back starts doing the pulling or a shoulder pinches forward, release the handle and tap Swaps.', 'Find the low cable station facing two footplates, often at the end of a tower; start around 10-20 kg.', '["Sit tall before you move the handle.","Drive your elbows behind you toward your back pockets.","Pause when the handle reaches your lower ribs."]'::jsonb, '["Do not lean far back to finish; that turns the rep into a body swing.","Do not shrug as the handle comes in.","Do not let the stack yank your shoulders forward."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-row-unilateral', '["Place one knee and the same-side hand on a flat bench, with the other foot firm on the floor.","Hold a dumbbell in the free hand and let that arm hang straight below your shoulder.","Make your back long and keep both hip bones facing the floor.","Pull your elbow toward your back pocket, pause, then lower until the arm is long."]'::jsonb, 'The side and upper back of the working arm doing the pull, with your hips steady on the bench.', 'If your support shoulder collapses or your lower back twists or aches, set the dumbbell down and tap Swaps.', 'Use a flat bench beside the dumbbell rack and start with one 6-10 kg dumbbell.', '["Press the support hand into the bench.","Pull your elbow toward the hip, not straight toward the ceiling.","Let the working arm lengthen fully at the bottom."]'::jsonb, '["Do not roll your chest open to lift the dumbbell higher.","Do not curl the weight toward your armpit.","Do not shrug the working shoulder toward your ear."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('bodyweight-assisted-chin-up', '["Set the assistance pin around 30-50 kg; more stack weight means more help and an easier pull-up.","Climb the steps, take an overhand grip, and place one knee at a time on the moving pad.","Start with long arms and a quiet body, keeping your shoulders away from your ears.","Pull your chest toward the handles until your chin reaches hand height, then lower slowly."]'::jsonb, 'The sides of your back and your biceps working while your body stays quiet over the moving pad.', 'If a shoulder pinches in the hang or an elbow feels sharply strained, let the pad rise and tap Swaps.', 'Find the tall Gravitron by the cable towers, with steps and a moving knee pad; start with 30-50 kg of help.', '["Add more assistance whenever you need the rep to feel easier.","Bring your elbows down toward your ribs.","Control the knee pad instead of letting it bounce."]'::jsonb, '["Do not jump off while the pad is still below you.","Do not kick or swing to get your chin higher.","Do not crane your neck over the handles."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('machine-rear-deltoid-row', '["Adjust the seat so the handles sit near shoulder height and your chest rests fully on the pad.","Choose 5-15 kg on the pin and take the handles with palms facing the floor.","Keep your chest on the pad and begin with arms reaching forward.","Pull your elbows wide until your hands reach your ribs, then return without dropping the stack."]'::jsonb, 'The backs of your shoulders and upper back working, with your chest supported and neck relaxed.', 'If the front of a shoulder pinches or your hands tingle, stop, change the seat or grip, and tap Swaps.', 'Look near the chest and back machines for a chest pad with handles that sweep back; start around 5-15 kg.', '["Keep your chest touching the pad throughout the pull.","Drive your elbows wide and back.","Pause just before the plates touch down."]'::jsonb, '["Do not tuck your elbows close; that turns it into a different row.","Do not push your head toward the handles.","Do not lean away from the chest pad to gain distance."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-lateral-raise', '["Choose two light dumbbells and stand with feet hip-width apart.","Hold the weights beside your thighs with palms facing in and elbows softly bent.","Lift your arms out to the sides, leading with the elbows.","Stop around shoulder height, then lower the dumbbells slowly to your sides."]'::jsonb, 'The outer part of your shoulders working, with your ribs, feet, and neck staying quiet.', 'If the top of a shoulder pinches or your neck takes over, lower the weights and tap Swaps.', 'Pick 2-5 kg dumbbells from the light end of the rack, often the top shelf by the mirrors.', '["Lead with your elbows so your hands stay relaxed.","Use a weight that lets your torso stay still.","Stop when your hands reach about shoulder height."]'::jsonb, '["Do not swing your knees and hips to launch the weights.","Do not shrug your shoulders toward your ears.","Do not tip your thumbs toward the floor; that can crowd the shoulder."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dumbbell-curl', '["Choose two dumbbells and stand tall with feet hip-width apart.","Let your arms hang by your sides, palms forward, and elbows close to your ribs.","Curl the dumbbells toward your shoulders without moving your upper arms.","Pause before your elbows drift forward, then lower until your arms are long."]'::jsonb, 'The fronts of your upper arms working, with your torso still and your wrists straight.', 'If the crease of an elbow feels sharp or a wrist bends back under the load, set the weights down and tap Swaps.', 'Choose 3-7 kg dumbbells from the lighter half of the rack and stand clear of the bench aisle.', '["Keep your elbows beside your ribs.","Turn your palms fully forward as you curl.","Lower until the elbows open without snapping straight."]'::jsonb, '["Do not swing your hips to start the dumbbells.","Do not carry your elbows forward as the weights rise.","Do not fold your wrists toward your shoulders."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('cable-rope-pushdown', '["Clip a rope to the highest cable setting and choose 5-12.5 kg on the pin.","Face the tower, hold one rope end in each hand, and tuck your elbows beside your ribs.","Take a small step back and keep your knees soft with your chest tall.","Press the rope down, separate its ends by your thighs, then return using only your forearms."]'::jsonb, 'The backs of your upper arms working, with your shoulders down and your torso still.', 'If an elbow or wrist pinches or a shoulder gets pulled forward, release the rope and tap Swaps.', 'Use a cable tower and the rope from its attachment rack; set the pulley high and start around 5-12.5 kg.', '["Pin your elbows beside your body.","Split the rope ends at the bottom.","Let your forearms return without moving your upper arms."]'::jsonb, '["Do not lean your body weight onto the rope.","Do not flare your elbows away from your ribs.","Do not let the pin stack slam on the return."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('plank', '["Place a mat down and set your forearms parallel, with elbows directly below your shoulders.","Step both feet back onto your toes, about hip-width apart.","Squeeze your glutes and tighten your middle until head, hips, and heels form one line.","Hold that position for the timer while taking small, steady breaths."]'::jsonb, 'Your abs, glutes, and shoulders holding you still, with weight even between forearms and toes.', 'If your lower back sags or pinches or your shoulders fail before your abs, lower your knees and tap Swaps.', 'Take a mat to the stretching or core area and leave enough room to lie full length.', '["Push your forearms firmly into the floor.","Tuck your tail slightly so your lower back stays level.","Keep breathing while the timer runs."]'::jsonb, '["Do not hold your breath to survive the last seconds.","Do not let your hips sag below your shoulders.","Do not lift your hips high to take the work off your abs."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('cable-rope-kneeling-crunch', '["Clip a rope to the highest cable setting, place a mat down, and choose 10-20 kg.","Kneel facing the tower about one long step away and hold the rope ends beside your temples.","Keep your hips over your knees and your hands still as you curl your ribs toward your hips.","Pause low, then uncurl slowly until your abs lengthen without letting the stack rest."]'::jsonb, 'The front of your abs doing the curl, with your hips steady and your arms only holding the rope.', 'If your lower back pinches or the rope pulls on your neck, lighten the pin or tap Swaps.', 'Find a cable tower, a rope, and a mat; use the high pulley and start around 10-20 kg.', '["Keep the rope beside your head.","Curl your ribs toward your hips.","Open slowly until your abs feel long again."]'::jsonb, '["Do not pull the rope down with your arms.","Do not sit your hips back onto your heels.","Do not drop only your head while the rest of your torso stays still."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('crunches', '["Lie on a mat with knees bent, feet flat, and lower back resting comfortably.","Place your fingertips lightly behind your ears or cross your hands over your chest.","Look at the ceiling and curl your ribs toward your hips until your shoulder blades lift.","Pause, then lower your upper back slowly without letting your head drop."]'::jsonb, 'The front of your abs working, with your lower back heavy and your neck relaxed.', 'If your neck strains, your head aches, or your lower back lifts and hurts, lower down and tap Swaps.', 'Use any mat in the stretching area; you need only enough floor space to lie down.', '["Keep your eyes on one spot above you.","Lift your shoulder blades, not your whole back.","Breathe out as your ribs curl up."]'::jsonb, '["Do not pull your head forward with your hands.","Do not sit all the way up; that shifts the work away from your abs.","Do not hook your feet under a bench to force extra reps."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('elbow-side-plank', '["Lie on one side on a mat and place your lower elbow directly below your shoulder.","Straighten both legs and stack your feet, or place the top foot slightly in front for balance.","Press your forearm down and lift your hips until your head, hips, and feet form one line.","Hold for the timer with your top hand on your hip, then lower and switch sides."]'::jsonb, 'Your lower-side waist, side glute, and support shoulder working while your body stays stacked.', 'If the support shoulder pinches or you cannot keep your hips lifted, lower the bottom knee and tap Swaps.', 'Take a mat to the edge of the stretching area so you have room to switch sides.', '["Press the full forearm into the mat.","Stack your top hip directly above the lower one.","Stagger your feet if stacked feet make you wobble."]'::jsonb, '["Do not sink the support shoulder toward your ear.","Do not roll your chest toward the floor.","Do not let your hips drift behind your body."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz),
  ('dead-bug', '["Lie on your back with both arms reaching up and knees bent above your hips.","Set your shins parallel to the floor and gently press your lower back into the mat.","Slowly reach one arm overhead as the opposite leg extends away from you.","Stop before your back lifts, return to the start, and change sides."]'::jsonb, 'Your deep abs working around your waist, with your lower back staying quietly against the mat.', 'If your lower back lifts or the front of a hip pinches as the leg lowers, shorten the reach or tap Swaps.', 'Use a mat in the stretching area with clear space above your head and beyond your feet.', '["Move opposite arm and leg together.","Breathe out as your limbs reach away.","Make the reach smaller if your back wants to lift."]'::jsonb, '["Do not lower both legs together.","Do not rush through the side change.","Do not reach so far that your lower back arches off the mat."]'::jsonb, '2026-07-26T00:00:00.000Z'::timestamptz)
on conflict (exercise_id) do update set
  setup_steps = excluded.setup_steps,
  should_feel = excluded.should_feel,
  stop_if = excluded.stop_if,
  find_it = excluded.find_it,
  dos = excluded.dos,
  donts = excluded.donts,
  updated_at = excluded.updated_at;

